#!/usr/bin/env bash
set -euo pipefail

REPO_URL="https://github.com/peteywee/topshelf-operating-system.git"
TARGET="${1:-$HOME/projects/topshelf-operating-system}"
EXPECTED_FILES=139
EXPECTED_SHA256="d45a474f46d4709069b9a22197a3f4b723492c1503b535f27bb0af7c6a5d3ca4"

command -v git >/dev/null || { echo "ERROR: git is required."; exit 1; }
command -v tar >/dev/null || { echo "ERROR: tar is required."; exit 1; }
command -v base64 >/dev/null || { echo "ERROR: base64 is required."; exit 1; }
command -v sha256sum >/dev/null || { echo "ERROR: sha256sum is required."; exit 1; }

mkdir -p "$(dirname "$TARGET")"
if [[ ! -d "$TARGET/.git" ]]; then
  if [[ -e "$TARGET" && -n "$(ls -A "$TARGET" 2>/dev/null || true)" ]]; then
    echo "ERROR: $TARGET exists and is not an empty Git repository."
    exit 1
  fi
  rm -rf "$TARGET"
  git clone "$REPO_URL" "$TARGET"
fi

cd "$TARGET"
if [[ -n "$(git status --porcelain)" ]]; then
  echo "ERROR: Repository has uncommitted changes. Commit or stash them first."
  exit 1
fi

TMP_DIR="$(mktemp -d)"
trap 'rm -rf "$TMP_DIR"' EXIT
PAYLOAD="$TMP_DIR/tos-foundation.tar.gz"

cat > "$TMP_DIR/payload.b64" <<'TOS_PAYLOAD'

TOS_PAYLOAD

base64 --decode "$TMP_DIR/payload.b64" > "$PAYLOAD"
echo "$EXPECTED_SHA256  $PAYLOAD" | sha256sum --check --status || {
  echo "ERROR: Embedded payload checksum failed."
  exit 1
}

tar -xzf "$PAYLOAD" -C "$TARGET"

ACTUAL_FILES="$(find . -type f -not -path './.git/*' | wc -l | tr -d ' ')"
if [[ "$ACTUAL_FILES" != "$EXPECTED_FILES" ]]; then
  echo "ERROR: Expected $EXPECTED_FILES files, found $ACTUAL_FILES."
  exit 1
fi

git add -A
if git diff --cached --quiet; then
  echo "TOS foundation is already present; nothing to commit."
else
  git commit -m "feat: establish TopShelf Operating System foundation v2.0"
fi

git push -u origin HEAD:main

echo
echo "SUCCESS: TopShelf Operating System foundation published."
echo "Repository: $REPO_URL"
echo "Files: $ACTUAL_FILES"
echo "Commit: $(git rev-parse HEAD)"
